WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, order_id, method, amount, paid_at, status, is_new_burst, session_id, CASE WHEN method RLIKE '^(paypal|bank_transfer)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS method_zone FROM sessionized
